import {createInteriors} from './interiors.js';
import {STORY_TITLE,CAST,objective,storyDestination,storyItems,advanceStory,conversation,conversationBranch} from './story.js';
export function createQuestExperience(renderer,{getState,save,toast,keys,onExit,onCourse}){
const $=id=>document.getElementById(id);document.body.insertAdjacentHTML('beforeend',`<section id="room-ui" hidden><div class="room-heading"><div><small id="room-city"></small><h1 id="room-title"></h1></div><button id="leave-room">Return to ship <span>Esc</span></button></div><div class="room-story"><small>A PERSONAL STORY</small><span>${STORY_TITLE}</span></div><div class="room-controls"><div><b>Walk & explore</b><span>WASD / arrow keys · Click the floor to walk</span><span>Click a character to approach and talk</span></div><button id="room-talk">Approach a character <kbd>E</kbd></button><div id="room-people" aria-label="Characters in this room"></div></div></section><dialog id="story-dialogue" aria-labelledby="speaker-name" aria-describedby="speaker-text"><div class="portrait" id="speaker-portrait" role="img"></div><div class="dialogue-copy"><div class="dialogue-top"><div><small id="speaker-role"></small><h2 id="speaker-name"></h2></div><button id="dialogue-close" aria-label="Leave conversation">✕</button></div><p id="speaker-text"></p><div id="dialogue-choices"></div></div></dialog>`);
const dialog=$('story-dialogue');let lastSpeaker=null;const room=createInteriors(renderer,{talk:openConversation,onNearby(id){$('room-talk').textContent=id?`Talk to ${CAST[id].name} · E`:'Approach a character · E';}});
function closeDialogue(){dialog.close();keys.clear();$('room-talk').focus({preventScroll:true});}
function showNode(node){lastSpeaker=node.speaker;const c=CAST[node.speaker];$('speaker-name').textContent=c.name;$('speaker-role').textContent=c.role;$('speaker-text').textContent=node.text;$('speaker-portrait').style.backgroundPosition=`${c.portrait%2*100}% ${Math.floor(c.portrait/2)*100}%`;$('speaker-portrait').setAttribute('aria-label',`Portrait of ${c.name}`);const choices=$('dialogue-choices');choices.replaceChildren();for(const option of node.choices){const b=document.createElement('button');b.textContent=option.label;b.onclick=()=>{if(option.close){closeDialogue();return;}if(option.next){showNode(option.next==='start'?conversation(getState(),lastSpeaker):conversationBranch(getState(),lastSpeaker,option.next));return;}if(option.action){const result=advanceStory(getState(),option.action,room.place);if(!result.ok){toast(result.message);closeDialogue();return;}save();toast(result.message);showNode({speaker:lastSpeaker,text:option.after,choices:[{label:'Continue',close:true}]});}};choices.append(b);}if(dialog.open)choices.firstElementChild?.focus({preventScroll:true});}
function openConversation(id){if(dialog.open)return;keys.clear();showNode(conversation(getState(),id));dialog.showModal();}
$('dialogue-close').onclick=closeDialogue;dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialogue();});dialog.addEventListener('close',()=>keys.clear());$('room-talk').onclick=()=>room.interact();
function enter(place){keys.clear();room.enter(place);document.body.classList.add('in-room');$('room-ui').hidden=false;$('room-city').textContent=place==='lisbon'?'LISBON · PORTUGAL':place==='london'?'LONDON · ENGLAND':'AZORES · ATLANTIC OCEAN';$('room-title').textContent=place==='lisbon'?'The Lantern & Tide':place==='london'?'The Merchant Guild':'The Morning Star wreck camp';$('room-people').replaceChildren();for(const id of room.people){const b=document.createElement('button');b.textContent=`Approach ${CAST[id].name}`;b.onclick=()=>room.approach(id);$('room-people').append(b);}$('world').setAttribute('aria-label','Walkable three-dimensional scene. Use WASD or click the floor; approach a character and press E.');$('leave-room').focus();}
function exit(){if(dialog.open)closeDialogue();keys.clear();room.exit();document.body.classList.remove('in-room');$('room-ui').hidden=true;$('world').setAttribute('aria-label','Three-dimensional sailing world');save();onExit();}
$('leave-room').onclick=exit;
return{room,enter,exit,get dialogueOpen(){return dialog.open;},key(e){if(!room.active)return false;if(dialog.open)return true;const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys.add(k);if(!e.repeat){if(k==='e')room.interact();if(k==='escape')exit();}return true;},journal(){const s=getState();return`<div class="journal-entry story-entry"><small>${s.story.phase==='complete'?'STORY COMPLETE':'PERSONAL STORY'}</small><h3>${STORY_TITLE}</h3><p>${objective(s)}</p><p class="story-items">${storyItems(s).length?'Keepsakes: '+storyItems(s).join(' · '):'A lantern burns in a Lisbon tavern for a captain who has not come home.'}</p>${s.story.phase==='complete'?`<p>Companion: ${CAST[s.story.companion].name}</p>`:'<button class="action-btn" id="journal-story-course">Chart the next destination</button>'}</div>`;},bindJournal(){const b=$('journal-story-course');if(b)b.onclick=()=>onCourse(storyDestination(getState()));}};
}
